bounded_host_request.command:
set -eu
docker exec deploy-postgres-1 sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB"' <<'SQL'
BEGIN;
DO $$
DECLARE n int;
BEGIN
SELECT count(*) INTO n FROM posting_topics
 WHERE board_key='video_chat' AND chat_id=-1002373696859
 AND enabled=TRUE AND verified_by IS NOT NULL AND verified_at IS NOT NULL
 AND (title ILIKE '%稼げる有料動画投稿%' OR title ILIKE '%稼げる%有料動画%');
IF n <> 1 THEN RAISE EXCEPTION 'VIDEO_SALE_EXISTING_TOPIC_AMBIGUOUS: %',n; END IF;
SELECT count(*) INTO n FROM posting_topics WHERE purpose='video_sale' AND enabled=TRUE;
IF n > 1 THEN RAISE EXCEPTION 'MULTIPLE_SALE_ROUTES'; END IF;
IF n = 1 AND NOT EXISTS (
 SELECT 1 FROM posting_topics v JOIN posting_topics e
 ON v.chat_id=e.chat_id AND v.message_thread_id=e.message_thread_id
 WHERE v.purpose='video_sale' AND v.enabled=TRUE AND e.board_key='video_chat'
 AND e.chat_id=-1002373696859 AND e.verified_by IS NOT NULL
 AND e.enabled=TRUE AND (e.title ILIKE '%稼げる有料動画投稿%' OR e.title ILIKE '%稼げる%有料動画%')
) THEN RAISE EXCEPTION 'SALE_TOPIC_CONFLICT'; END IF;
END $$;
INSERT INTO posting_topics(board_key,purpose,chat_id,message_thread_id,title,verified_by,verified_at,enabled)
SELECT 'video_chat','video_sale',chat_id,message_thread_id,title,verified_by,verified_at,TRUE
 FROM posting_topics
 WHERE board_key='video_chat' AND chat_id=-1002373696859
 AND enabled=TRUE AND verified_by IS NOT NULL AND verified_at IS NOT NULL
 AND (title ILIKE '%稼げる有料動画投稿%' OR title ILIKE '%稼げる%有料動画%')
 ON CONFLICT (board_key,purpose,chat_id,message_thread_id) DO NOTHING;
COMMIT;
SELECT 'VIDEO_SALE_ROUTE_COUNT='||count(*) FROM posting_topics WHERE purpose='video_sale' AND enabled=TRUE;
SQL
